property.value:
//MethodDeclaration[Block][not(pmd-java:modifiers() = ('static', 'private'))]
  [ModifierList/Annotation[pmd-java:typeIs('org.springframework.cache.annotation.Cacheable')]
     /AnnotationMemberList/MemberValuePair[@Name = 'key']/StringLiteral]
  ! (let $method := .,
         $key := string(($method/ModifierList/Annotation[pmd-java:typeIs('org.springframework.cache.annotation.Cacheable')]
           /AnnotationMemberList/MemberValuePair[@Name = 'key']/StringLiteral/@ConstValue)[1]),
         $parameters := $method/FormalParameters/FormalParameter,
         $named := function($parameter) {
           let $i := count($parameter/preceding-sibling::FormalParameter)
           return matches($key, concat('#', $parameter/VariableId/@Name, '([^A-Za-z0-9_$]|$)'))
             or matches($key, concat('#[pa]', string($i), '([^0-9]|$)'))
         },
         $read := function($parameter) {
           exists($method/Block//VariableAccess[@Name = $parameter/VariableId/@Name]
             [count(ancestor::ClassBody) = count($method/ancestor::ClassBody)])
         }
     return if (contains($key, '#root.args')
                or (some $p in $parameters satisfies
                      ($p/ClassType[pmd-java:typeIsExactly('java.lang.String')] and $named($p) and not($read($p)))))
            then ()
            else $parameters[not($named(.)) and $read(.)])
